class Solution {
public:
    vector<int> nextLargerNodes(ListNode* head) {
        vector<int> ans;
        stack<pair<int,int>> st;
        int i = 0;
        while (head) {
            ans.push_back(0);
            while (!st.empty() && head->val > st.top().second) {
                ans[st.top().first] = head->val;
                st.pop();
            }
            st.push({i, head->val});
            head = head->next;
            i++;
        }
        return ans;
    }
};
